"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[3174],{68140(e){e.exports=JSON.parse('{"tag":{"label":"algebrization","permalink":"/azeon/p-vs-np/tags/algebrization","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"failed-proofs/summary-of-the-barriers","title":"Summary of the Barriers","description":"Phase 4 in one place: every barrier, what it blocks, what slips past it, and the 2011 result that showed a way around all of them for a weaker question. Why a proof may need mathematics that doesn\'t exist yet.","permalink":"/azeon/p-vs-np/failed-proofs/summary-of-the-barriers"},{"id":"failed-proofs/the-algebrization-barrier","title":"The Algebrization Barrier","description":"Arithmetization broke through the first barrier. In 2008, Aaronson and Wigderson upgraded relativization to cover it, and showed that the upgraded version still can\'t settle P vs NP. A second wall, right behind the first.","permalink":"/azeon/p-vs-np/failed-proofs/the-algebrization-barrier"},{"id":"failed-proofs/why-havent-we-solved-it","title":"Why Haven\'t We Solved It?","description":"Over fifty years, thousands of researchers, and almost no progress on the main question. It\'s not lack of effort. It\'s that mathematicians have proved, three separate times, that whole families of proof techniques cannot work.","permalink":"/azeon/p-vs-np/failed-proofs/why-havent-we-solved-it"}],"unlisted":false}}')}}]);